    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        window = sorted(nums[:k])
        res = []
        is_odd = (k % 2 == 1)
        mid = k // 2

        def get_median():
            if is_odd:
                return float(window[mid])
            return (window[mid - 1] + window[mid]) / 2.0

        res.append(get_median())
        for i in range(k, len(nums)):
            leaving = nums[i - k]
            entering = nums[i]
            idx = bisect.bisect_left(window, leaving)
            window.pop(idx)
            bisect.insort(window, entering)
            res.append(get_median())

        return res

class Solution {
public:
    vector<double> medianSlidingWindow(vector<int>& nums, int k) {
        multiset<long long> window(nums.begin(), nums.begin() + k);
        auto mid = next(window.begin(), (k - 1) / 2);
        vector<double> res;

        for (int i = k;; ++i) {
            if (k % 2 == 1) {
                res.push_back(*mid);
            } else {
                res.push_back(((double)*mid + *next(mid)) / 2.0);
            }

            if (i == nums.size()) break;

            window.insert(nums[i]);
            if (nums[i] < *mid) mid--;

            if (nums[i - k] <= *mid) mid++;
            window.erase(window.lower_bound(nums[i - k]));
        }
        return res;
    }
};

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        List<Long> window = new ArrayList<>();
        for (int i = 0; i < k; ++i) window.add((long) nums[i]);
        Collections.sort(window);
        double[] res = new double[nums.length - k + 1];
        int mid = k / 2;
        boolean isOdd = (k % 2 == 1);

        for (int i = k;; ++i) {
            if (isOdd) {
                res[i - k] = window.get(mid);
            } else {
                res[i - k] = (window.get(mid - 1) + window.get(mid)) / 2.0;
            }

            if (i == nums.length) break;

            long leaving = nums[i - k];
            int removeIdx = Collections.binarySearch(window, leaving);
            window.remove(removeIdx);

            long entering = nums[i];
            int addIdx = Collections.binarySearch(window, entering);
            if (addIdx < 0) addIdx = -(addIdx + 1);
            window.add(addIdx, entering);
        }
        return res;
    }
}

var medianSlidingWindow = function(nums, k) {
    const window = nums.slice(0, k).sort((a, b) => a - b);
    const res = [];
    const mid = Math.floor(k / 2);
    const isOdd = k % 2 === 1;

    function bisectLeft(arr, val) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] < val) l = m + 1;
            else r = m;
        }
        return l;
    }

    function getMedian() {
        if (isOdd) return window[mid];
        return (window[mid - 1] + window[mid]) / 2;
    }

    res.push(getMedian());
    for (let i = k; i < nums.length; ++i) {
        const leaving = nums[i - k];
        const entering = nums[i];
        const remIdx = bisectLeft(window, leaving);
        window.splice(remIdx, 1);
        const insIdx = bisectLeft(window, entering);
        window.splice(insIdx, 0, entering);
        res.push(getMedian());
    }
    return res;
};
